sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */ event) {

    var body = JSON.parse(event.parm2);

    template.print('<strong>Employee Name : </strong>' + body.employee_name + '<br><br>');
    template.print('<strong>Location : </strong>' + body.location + '<br><br>');
    template.print('<strong>Type of Request : </strong>' + body.type_of_request + '<br><br>');
    if (body.type_of_request == 'Others') {
        template.print('<strong>Specify the Other Type : </strong>' + body.other_type + '<br><br>');
    }
    template.print('<strong>Describe how your needs impact your ability to do your work or complete your workday : </strong>' + body.describe_how_your_needs_impact_your_ability + '<br><br>');
    template.print('<strong>Describe how your needs could be met with an accommodation : </strong>' + body.describe_how_your_needs_could_be_met_with_accommodation + '<br><br>');

    email.addAddress("cc", "wa-at@parl.gc.ca", "CEH-HRS-OHS-Disability-Advisors");


})(current, template, email, email_action, event);
